INSERT INTO `farmaci` (`id`, `immagine`, `nome_commerciale`, `descrizione`, `principio_attivo`, `forma_farmaceutica`, `dosaggio`, `produttore`, `obbligo_ricetta`, `created_at`) VALUES
(3, 'bustine_okidoki.png', 'OkiDoki Task', 'Analgesico ad effetto rapido contro il mal di testa causato da Ingegneria del Software', 'Ketoprofene', 'Bustine', '80 <abbr title=\"milligrammi\">mg</abbr>', 'SuperSano', 1, '2025-12-30 14:47:07'),
(4, 'box_compresse_paracetamolo.png', 'Paracetamolo Advanced', 'Analgesico e antipiretico indicato per il trattamento sintomatico di stati dolorosi e febbrili.', 'Paracetamolo', 'Compresse', '500 <abbr title=\"milligrammi\">mg</abbr>', 'PharmaLife', 0, '2026-01-19 16:24:35'),
(5, 'box_capsule_ibuprofene.png', 'Ibuprofene Fast', 'Antinfiammatorio non steroideo (FANS) per mal di testa, dolori mestruali e osteoarticolari.', 'Ibuprofene', 'Capsule molli', '400 <abbr title=\"milligrammi\">mg</abbr>', 'MediCorp', 0, '2026-01-19 16:24:35'),
(6, 'box_compresse_espirina.png', 'Espirina C-Effect', 'Trattamento sintomatico di febbre e raffreddore con vitamina C.', 'Acido Acetilsalicilico', 'Compresse effervescenti', '400 <abbr title=\"milligrammi\">mg</abbr> + 240 <abbr title=\"milligrammi\">mg</abbr>', 'HealthCare S.p.A.', 0, '2026-01-19 16:24:35'),
(7, 'bustine_ketoprofene.png', 'Ketoprofene Lisina', 'Antinfiammatorio per dolori di forte intensità, agisce rapidamente.', 'Ketoprofene', 'Bustine', '80 <abbr title=\"milligrammi\">mg</abbr>', 'MediCorp', 0, '2026-01-19 16:24:35'),
(8, 'bottle_sciroppo_paracetamolo.png', 'Paracetamolo Sciroppo', 'Antipiretico per bambini e adulti con difficoltà di deglutizione.', 'Paracetamolo', 'Sciroppo', '120 <abbr title=\"milligrammi\">mg</abbr> ogni 5 <abbr title=\"millilitri\">ml</abbr>', 'PediatricPharma', 0, '2026-01-19 16:24:35'),
(9, 'box_capsule_omeprazolo.png', 'Omeprazolo Gastro', 'Gastroprotettore, riduce la produzione di acido nello stomaco.', 'Omeprazolo', 'Capsule', '20 <abbr title=\"milligrammi\">mg</abbr>', 'Gastrolab', 1, '2026-01-19 16:24:35'),
(10, 'box_compresse_pantoprazolo.png', 'Pantoprazolo Protect', 'Trattamento del reflusso gastroesofageo e protezione gastrica.', 'Pantoprazolo', 'Compresse', '20 <abbr title=\"milligrammi\">mg</abbr>', 'Gastrolab', 1, '2026-01-19 16:24:35'),
(11, 'box_compresse_lactobacillus.png', 'Lactobacillus Complex', 'Favorisce l\'equilibrio della flora intestinale dopo antibiotici o stress.', 'Lactobacillus', 'Flaconcini', '10 Miliardi', 'BioNatura', 0, '2026-01-19 16:24:35'),
(12, 'box_compresse_sodio.png', 'Sodio Alginato Reflux', 'Sollievo rapido da bruciore di stomaco e indigestione.', 'Sodio Alginato', 'Compresse masticabili', '500 <abbr title=\"milligrammi\">mg</abbr>', 'PharmaLife', 0, '2026-01-19 16:24:35'),
(13, 'box_compresse_joscina.png', 'Joscina Busco', 'Antispastico per dolori e crampi addominali.', 'Butilscopolamina', 'Compresse', '10 <abbr title=\"milligrammi\">mg</abbr>', 'MediCorp', 0, '2026-01-19 16:24:35'),
(14, 'bottle_sciroppo_destrometorfano.png', 'Destrometorfano Sedativo', 'Calma la tosse secca e stizzosa, favorendo il riposo notturno.', 'Destrometorfano', 'Sciroppo', '30 <abbr title=\"milligrammi\">mg</abbr> ogni 10 <abbr title=\"millilitri\">ml</abbr>', 'RespiroBene', 0, '2026-01-19 16:24:35'),
(15, 'bustine_acetilcisteina.png', 'Acetilcisteina Flu', 'Scioglie il catarro e libera le vie respiratorie.', 'Acetilcisteina', 'Bustine', '600 <abbr title=\"milligrammi\">mg</abbr>', 'RespiroBene', 0, '2026-01-19 16:24:35'),
(16, 'spray_flacone_oximetazolina.png', 'Oximetazolina Spray', 'Libera il naso chiuso in caso di raffreddore o rinite.', 'Oximetazolina', 'Spray Nasale', '0.05 <abbr title=\"percento\">%</abbr>', 'NasoLibero', 0, '2026-01-19 16:24:35'),
(17, 'spray_flacone_flurbiprofene.png', 'Flurbiprofene Gola', 'Sollievo locale per mal di gola e irritazioni del cavo orale.', 'Flurbiprofene', 'Spray Orale', '0.25 <abbr title=\"percento\">%</abbr>', 'OralCare', 0, '2026-01-19 16:24:35'),
(18, 'tubo_crema_mentolo.png', 'Mentolo Balsamico', 'Balsamo per massaggi pettorali, aiuta a respirare meglio la notte.', 'Mentolo ed Eucalipto', 'Unguento', '50 <abbr title=\"grammi\">g</abbr>', 'NaturaMix', 0, '2026-01-19 16:24:35'),
(19, 'box_compresse_loratadina.png', 'Loratadina Allergy', 'Antistaminico per il sollievo dai sintomi della rinite allergica.', 'Loratadina', 'Compresse', '10 <abbr title=\"milligrammi\">mg</abbr>', 'AllergyStop', 0, '2026-01-19 16:24:35'),
(20, 'bottle_gocce_cetirizina.png', 'Cetirizina Gocce', 'Antistaminico per bambini e adulti, contro prurito e starnuti.', 'Cetirizina', 'Gocce', '10 <abbr title=\"milligrammi\">mg</abbr> per <abbr title=\"millilitro\">ml</abbr>', 'AllergyStop', 1, '2026-01-19 16:24:35'),
(21, 'tubo_crema_gentamicina.png', 'Gentamicina Beta', 'Antibiotico e cortisonico per infezioni e infiammazioni cutanee.', 'Gentamicina Betametasone', 'Crema', '0.1<abbr title=\"percento\">%</abbr> + 0.1<abbr title=\"percento\">%</abbr>', 'DermaCure', 1, '2026-01-19 16:24:35'),
(22, 'bottle_gocce_tobramicina.png', 'Tobramicina Collirio', 'Antibiotico per infezioni oculari batteriche.', 'Tobramicina', 'Collirio', '0.3 <abbr title=\"percento\">%</abbr>', 'OftaVision', 1, '2026-01-19 16:24:35'),
(23, 'tubo_crema_diclofenac.png', 'Diclofenac Gel', 'Antinfiammatorio locale per dolori muscolari e articolari.', 'Diclofenac Sodico', 'Gel', '1 <abbr title=\"percento\">%</abbr>', 'MuscleRelief', 0, '2026-01-19 16:24:35'),
(24, 'box_capsule_multivitaminico.png', 'Multivitaminico A-Z', 'Supporto energetico per stanchezza fisica e mentale.', 'Vitamine A-Z', 'Compresse', '1000 <abbr title=\"milligrammi\">mg</abbr>', 'VitaPlus', 0, '2026-01-19 16:24:35'),
(25, 'polvere_magnesio.png', 'Magnesio Supremo', 'Rilassa i muscoli e riduce la stanchezza.', 'Magnesio', 'Polvere Solubile', '300 <abbr title=\"grammi\">g</abbr>', 'VitaPlus', 0, '2026-01-19 16:24:35'),
(26, 'bottle_gocce_melatonina.png', 'Melatonina Sleep', 'Riduce il tempo richiesto per prendere sonno.', 'Melatonina', 'Gocce', '1 <abbr title=\"milligrammi\">mg</abbr>', 'NotteSerena', 0, '2026-01-19 16:24:35');
